/* Client accounts, reviews, platform administration and expanded barber tools. */
window.tunsproClient = null;
window.tunsproAdmin = null;
function favoriteShopIds(){try{return JSON.parse(localStorage.getItem('tunspro-favorites')||'[]').map(Number)}catch{return []}}

function shellHeader(right=''){
  return `<header class="subnav"><div class="wrap nav">${brand()}<nav class="navlinks" aria-label="Meniu principal"><a href="#cauta">Caută și rezervă</a><a href="#cum-functioneaza">Cum funcționează</a><a href="#barberi">Pentru barberi</a><a href="#preturi">Prețuri</a></nav><div class="navright">${right||'<a class="login" href="#login">Conectare frizerie</a><a class="btn" href="#connect">Înscrie frizeria ↗</a>'}</div></div></header>`;
}
function authPage(kind){
  if(kind==='login')return `${shellHeader('<a href="#connect">Înscrie frizeria ↗</a>')}<main class="success-wrap"><form id="auth-form" class="success-card connect-card"><div class="eyebrow" style="justify-content:center">PORTAL FRIZERII</div><h1>Conectează-te la dashboard.</h1><p>Gestionează agenda, serviciile, echipa și profilul frizeriei.</p><label class="field-label">E-mail<input required class="input" name="email" type="email" autocomplete="username"></label><label class="field-label">Parolă<input required class="input" name="password" type="password" autocomplete="current-password"></label><button class="btn full" style="margin-top:18px">Intră în dashboard →</button><p style="font-size:12px">Prima dată aici? <a href="#connect"><strong>Conectează-ți frizeria</strong></a></p></form></main>${siteFooter()}`;
  return `${shellHeader('<a href="#login">Ai deja cont? Conectare</a>')}<main class="success-wrap"><form id="auth-form" class="success-card connect-card barber-onboarding"><div class="eyebrow" style="justify-content:center">ÎNSCRIERE FRIZERIE · GRATUIT</div><h1>Hai să-ți pregătim prezența pe TunsPro.</h1><p>În trei pași creezi contul și pregătești profilul. Serviciile, echipa și programul le poți ajusta apoi din dashboard.</p><div class="onboarding-progress" aria-label="Etapele înscrierii"><span data-onboarding-indicator="1" class="active">1 <small>Cont</small></span><i></i><span data-onboarding-indicator="2">2 <small>Frizerie</small></span><i></i><span data-onboarding-indicator="3">3 <small>Verificare</small></span></div><fieldset class="onboarding-step" data-onboarding-step="1"><legend>Contul administratorului</legend><label class="field-label">Numele tău<input required class="input" name="owner" autocomplete="name" placeholder="ex. Andrei Popescu"></label><label class="field-label">E-mail de conectare<input required class="input" name="email" type="email" autocomplete="email" placeholder="tu@frizerie.ro"></label><label class="field-label">Parolă<input required class="input" name="password" type="password" minlength="10" autocomplete="new-password" placeholder="Minimum 10 caractere"></label><small class="manage-note">Acest cont îți oferă acces securizat la dashboardul frizeriei.</small><button type="button" class="btn full onboarding-next" data-onboarding-next>Continuă la datele frizeriei →</button></fieldset><fieldset class="onboarding-step" data-onboarding-step="2" hidden><legend>Profilul frizeriei</legend><label class="field-label">Numele frizeriei<input required class="input" name="name" placeholder="ex. Barber House"></label><div class="connect-fields"><label class="field-label">Oraș<input required class="input" name="city" placeholder="ex. Urziceni"></label><label class="field-label">Telefon<input required class="input" name="phone" type="tel" autocomplete="tel" placeholder="07xx xxx xxx"></label></div><label class="field-label">Adresă<input required class="input" name="address" placeholder="Stradă și număr"></label><label class="field-label">Descriere scurtă <small>(opțional)</small><input class="input" name="tagline" maxlength="140" placeholder="Ce te diferențiază?"></label><div class="onboarding-actions"><button type="button" class="btn ghost" data-onboarding-back>← Înapoi</button><button type="button" class="btn" data-onboarding-next>Verifică datele →</button></div></fieldset><fieldset class="onboarding-step" data-onboarding-step="3" hidden><legend>Verifică înainte să creezi contul</legend><p class="manage-note">Aceste informații formează profilul inițial. Le vei putea modifica oricând din dashboard.</p><dl class="onboarding-review" data-onboarding-review></dl><div class="onboarding-actions"><button type="button" class="btn ghost" data-onboarding-back>← Modifică datele</button><button type="submit" class="btn">Creează contul frizeriei →</button></div><p class="privacy-inline">Profilul public și rezervările se activează după alegerea unui plan plătit. <a href="#confidentialitate">Confidențialitate</a></p></fieldset><p class="onboarding-login">Ai deja cont? <a href="#login"><strong>Conectează-te aici</strong></a></p></form></main>${siteFooter()}`;
}
function setOnboardingStep(form,step){form.dataset.onboardingStep=String(step);form.querySelectorAll('[data-onboarding-step]').forEach(panel=>panel.hidden=panel.dataset.onboardingStep!==String(step));form.querySelectorAll('[data-onboarding-indicator]').forEach(item=>{item.classList.toggle('active',Number(item.dataset.onboardingIndicator)<=step)})}
function siteFooter(){return `<footer class="footer"><div class="wrap"><span>© 2026 TunsPro</span><a href="#despre">Despre</a><a href="#preturi">Prețuri</a><a href="#confidentialitate">Confidențialitate</a><a href="#admin-login">Admin</a><a href="mailto:tunsprogramari@gmail.com">Contact</a></div></footer>`}
function privacyPage(){return `${shellHeader()}<main class="wrap legal-page"><div class="eyebrow">Informații juridice</div><h1>Politica de confidențialitate</h1><p class="legal-updated">Ultima actualizare: 7 octombrie 2026</p><p>TunsPRO este un brand operat de <strong>Ion Andrei Ronaldo</strong>. Pentru întrebări despre datele personale: <a href="mailto:tunsprogramari@gmail.com">tunsprogramari@gmail.com</a>, Strada Ghiocei Nr. 11A, Urziceni, județul Ialomița.</p><h2>Datele clienților</h2><p>Nu este necesar un cont de client pentru rezervare. Pentru programare colectăm numele, numărul de telefon și adresa de e-mail, pe care le folosim pentru administrarea rezervării și confirmările prin SMS și e-mail atunci când serviciile respective sunt configurate. Favoritele salvate pe dispozitiv rămân în memoria locală a browserului.</p><p>Frizeria aleasă vede datele necesare administrării programării. Recenziile publicate afișează evaluarea și comentariul, fără numele sau e-mailul clientului. Datele de identificare din rezervări sunt anonimizate automat la 12 luni după programare.</p><h2>Datele frizeriilor și abonamentele</h2><p>Prelucrăm datele contului frizeriei, profilul, echipa, serviciile, programul și fotografiile pentru furnizarea dashboardului și profilului public. Identificatorii și starea abonamentului sunt gestionate pentru accesul prin Stripe Checkout; TunsPRO nu stochează datele cardului. Administratorul platformei poate vedea conturile frizeriilor, programările și starea abonamentelor pentru administrarea serviciului și poate suspenda vizibilitatea unui profil.</p><h2>Păstrare și ștergere</h2><p>Datele de identificare ale clientului din rezervări sunt anonimizate automat la 12 luni după încheiere. Favoritele salvate în browser pot fi eliminate individual sau șterse prin golirea datelor locale ale browserului. Solicitările de acces, rectificare sau ștergere pot fi trimise la e-mailul de contact. Unele informații pot fi păstrate când legea o cere.</p><h2>Furnizori și securitate</h2><p>Aplicația este găzduită de Render. Stripe procesează abonamentele; SMTP și Twilio sunt folosite doar când sunt configurate. Fonturile și biblioteca QR sunt încărcate de la Google Fonts și Cloudflare CDN și pot transmite date tehnice de conexiune. Folosim parole hash-uite și cookie-uri HttpOnly de sesiune; autentificarea frizeriilor și a administratorului este separată și configurată prin variabile protejate pe server.</p><h2>Drepturile tale</h2><p>În condițiile legii, poți solicita accesul, rectificarea, ștergerea, restricționarea prelucrării sau portabilitatea și poți depune o plângere la <a href="https://www.dataprotection.ro/" target="_blank" rel="noopener">ANSPDCP</a>. Contact: <a href="mailto:tunsprogramari@gmail.com">tunsprogramari@gmail.com</a>.</p><p class="legal-note">Această pagină descrie funcțiile actuale și va fi actualizată când se modifică datele sau furnizorii utilizați.</p></main>${siteFooter()}`}
function home(){return `${shellHeader('<a class="login" href="#login">Conectare frizerie</a><a class="btn" href="#connect">Înscrie frizeria ↗</a>')}<section class="hero"><div class="wrap hero-grid"><div><div class="eyebrow">Găsește-ți următorul barber</div><h1>Un tuns bun<br>începe cu o<br><span>programare simplă.</span></h1><p class="hero-copy">Descoperă frizerii active, compară serviciile și rezervă online. Confirmi cu numele, telefonul și e-mailul, fără să-ți creezi cont.</p><div class="hero-actions"><a class="btn lime" href="#cauta">Găsește barber <span>↗</span></a><a class="btn ghost" href="#cum-functioneaza">Cum funcționează</a></div><div class="socialproof"><span>Serviciu · frizer · zi · oră</span></div></div><div class="hero-visual"><span class="visual-tag">✦ Rezervare în câteva secunde</span><div class="barber-art">💈</div><div class="booking-card"><div class="booking-top"><div><strong>Alege ce ți se potrivește.</strong><br>Frizerii cu programări active</div><span>✂</span></div><div class="mini-slots"><span>Serviciu</span><span class="active">Barber</span><span>Dată</span><span>Oră</span></div></div></div></div></section><section class="section" id="cum-functioneaza"><div class="wrap"><div class="section-head"><div><div class="eyebrow">Pentru clienți</div><h2>Găsești. Alegi.<br>Te-ai programat.</h2></div><p class="section-sub">Alege o frizerie, verifică serviciile și orele libere, apoi confirmă cu numele, telefonul și e-mailul. Nu este necesar un cont de client.</p></div><div class="steps"><article class="step"><span class="step-icon">⌕</span><span class="step-num">01 / DESCOPERĂ</span><h3>Găsește un barber</h3><p>Caută după nume, oraș sau serviciu și folosește filtrele pentru rezultate potrivite.</p></article><article class="step"><span class="step-icon">◷</span><span class="step-num">02 / ALEGE</span><h3>Serviciu și disponibilitate</h3><p>Compară prețurile și alege frizerul, ziua și ora care îți convin.</p></article><article class="step"><span class="step-icon">✓</span><span class="step-num">03 / REZERVĂ</span><h3>Confirmare rapidă</h3><p>Rezervarea ajunge direct în agenda frizeriei. Confirmi cu numele, telefonul și e-mailul.</p></article></div></div></section>${siteFooter()}`}

function directoryCard(s){const favorite=favoriteShopIds().includes(Number(s.id));const mapUrl='https://www.openstreetmap.org/search?query='+encodeURIComponent(`${s.address}, ${s.city}`);return `<article class="directory-card"><div class="directory-cover">${s.photos?.[0]?`<img src="${esc(s.photos[0])}" alt="Fotografie: ${esc(s.name)}" loading="lazy">`:'<span>✂</span>'}<span class="pill">PROGRAMĂRI ACTIVE</span></div><div class="directory-content"><div class="directory-person"><span class="barber-face">💈</span><div><h2>${esc(s.name)}</h2><small>${esc(s.tagline||'Frizerie')}</small></div><span class="directory-rating">${s.review_count?`★ ${s.rating} (${s.review_count})`:'Profil nou'}</span></div><h3>${esc(s.city)}</h3><p>📍 ${esc(s.address)}</p><div class="directory-tags">${s.services.slice(0,3).map(x=>`<span>${esc(x.name)} · ${x.price} lei</span>`).join('')}</div><div class="directory-card-actions"><a class="btn full" href="#frizerie/${encodeURIComponent(s.slug)}">Vezi profilul și rezervă</a><button class="favorite-button" type="button" data-favorite-shop="${s.id}" data-favorited="${favorite}">${favorite?'♥ Salvat pe acest dispozitiv':'♡ Salvează pe acest dispozitiv'}</button><a class="map-link" href="${mapUrl}" target="_blank" rel="noopener">↗ Hartă și indicații</a></div></div></article>`}
async function searchPage(query=''){
  const d=await api('/api/public/shops');window.tunsproDirectoryCache=d.shops;
  const cities=[...new Set(d.shops.map(s=>s.city).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'ro'));
  const services=[...new Set(d.shops.flatMap(s=>s.services.map(x=>x.name)))].sort((a,b)=>a.localeCompare(b,'ro'));
  return `${shellHeader()}<main class="wrap directory-main"><div class="eyebrow">Descoperă frizerii cu programări active</div><h1>Găsește-ți următorul<br><span>barber.</span></h1><p class="directory-lead">Caută după nume, oraș, frizer sau serviciu. Rezervarea nu necesită cont de client.</p><div class="directory-search"><span>⌕</span><input id="shop-search" type="search" value="${esc(query)}" placeholder="ex. fade, Andrei, București" autocomplete="off"><kbd>/</kbd></div><div class="directory-filters"><label>Oraș<select class="input" id="filter-city"><option value="">Toate orașele</option>${cities.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('')}</select></label><label>Serviciu<select class="input" id="filter-service"><option value="">Toate serviciile</option>${services.map(s=>`<option value="${esc(s)}">${esc(s)}</option>`).join('')}</select></label><label>Ordonează<select class="input" id="sort-results"><option value="name">Nume</option><option value="price">Preț minim</option><option value="rating">Evaluare</option></select></label></div><div class="directory-results"><strong id="result-count"></strong><span>Frizerii cu abonament activ</span></div><div id="search-results" class="directory-grid"></div><div class="empty-results hidden"><span>⌕</span><h2>Nu am găsit frizerii disponibile.</h2><p>Apar aici doar frizeriile cu abonament activ. Încearcă alt filtru sau revino mai târziu.</p><p>Ai o frizerie? <a href="#connect"><strong>Creează profilul</strong></a></p></div></main>${siteFooter()}`;
}
function renderDirectoryResults(){const box=document.querySelector('#search-results');if(!box)return;const fold=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('ro');const term=fold(document.querySelector('#shop-search')?.value).trim(),city=document.querySelector('#filter-city')?.value||'',service=document.querySelector('#filter-service')?.value||'',sort=document.querySelector('#sort-results')?.value||'name';let rows=(window.tunsproDirectoryCache||[]).filter(s=>{const text=fold([s.name,s.city,s.address,s.tagline,...s.team.map(t=>t.name),...s.services.map(x=>x.name)].join(' '));return(!term||text.includes(term))&&(!city||s.city===city)&&(!service||s.services.some(x=>x.name===service))});if(sort==='price')rows.sort((a,b)=>Math.min(...a.services.map(s=>s.price),Infinity)-Math.min(...b.services.map(s=>s.price),Infinity));else if(sort==='rating')rows.sort((a,b)=>(b.rating||0)-(a.rating||0));else rows.sort((a,b)=>a.name.localeCompare(b.name,'ro'));box.innerHTML=rows.map(directoryCard).join('');const count=document.querySelector('#result-count');if(count)count.textContent=`${rows.length} ${rows.length===1?'frizerie găsită':'frizerii găsite'}`;document.querySelector('.empty-results')?.classList.toggle('hidden',!!rows.length)}

async function profilePage(slug){
  const {shop}=await api('/api/public/shops/'+encodeURIComponent(slug));if(publicShop&&publicShop.slug!==slug)publicSelection={service:'',staff:'',date:'',time:''};publicShop=shop;
  if(!publicSelection.service&&shop.services[0])publicSelection.service=String(shop.services[0].id);if(!publicSelection.staff&&shop.team[0])publicSelection.staff=String(shop.team[0].id);if(!publicSelection.date){const d=new Date();d.setDate(d.getDate()+1);publicSelection.date=d.toISOString().slice(0,10)}
  const mapUrl='https://www.openstreetmap.org/search?query='+encodeURIComponent(`${shop.address}, ${shop.city}`);
  const reviewList=shop.reviews?.length?shop.reviews.map(r=>`<article class="public-review"><strong>${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</strong><p>${esc(r.comment||'Fără comentariu.')}</p><small>Client TunsPro · ${fmtDate(r.created)}</small></article>`).join(''):'<p class="manage-note">Încă nu există recenzii pentru această frizerie.</p>';
  const dayNames=['Luni','Marți','Miercuri','Joi','Vineri','Sâmbătă','Duminică'];const chosenBarber=shop.team.find(t=>String(t.id)===publicSelection.staff);const hours=chosenBarber?.weekly_schedule||{};
  return `${shellHeader('<a href="#cauta">← Înapoi la căutare</a>')}<main class="wrap profile-page"><section class="salon-hero"><div class="salon-identity"><span class="pill">PROGRAMĂRI ONLINE ACTIVE</span><h1>${esc(shop.name)}</h1><div class="salon-meta"><span>📍 ${esc(shop.address)}, ${esc(shop.city)}</span><span>✦ ${esc(shop.tagline||'Frizerie')}</span><span>${shop.review_count?`★ ${shop.rating} · ${shop.review_count} recenzii`:'Profil nou'}</span></div><a class="profile-map-link" href="${mapUrl}" target="_blank" rel="noopener">Deschide locația pe hartă ↗</a><a class="profile-map-link" href="tel:${esc(shop.phone)}">Sună frizeria · ${esc(shop.phone)}</a></div></section><nav class="profile-tabs"><button type="button" data-profile-scroll="galerie">Galerie</button><button type="button" data-profile-scroll="servicii">Servicii și prețuri</button><button type="button" data-profile-scroll="program">Program</button><button type="button" data-profile-scroll="disponibilitate">Disponibilitate</button><button type="button" data-profile-scroll="recenzii">Recenzii (${shop.review_count||0})</button></nav>${galleryMarkup(shop)||'<section class="profile-empty-gallery"><span>✂</span><p>Frizeria pregătește fotografiile de prezentare.</p></section>'}<div class="salon-grid"><section class="salon-main"><section id="servicii"><h2>Servicii și prețuri</h2><div class="service-list">${shop.services.map(s=>`<button class="service ${String(s.id)===publicSelection.service?'selected':''}" data-select-service="${s.id}"><span><strong>${esc(s.name)}</strong><small>${s.duration} min · ${esc(s.description||'')}</small></span><span class="service-price">${s.price} lei</span></button>`).join('')}</div></section><section id="echipa" class="profile-section"><h2>Alege barberul</h2><div class="barbers">${shop.team.map(t=>`<button class="barber ${String(t.id)===publicSelection.staff?'selected':''}" data-select-staff="${t.id}"><span class="barber-face">✂</span><span><strong>${esc(t.name)}</strong><small>${esc(t.role)}</small></span></button>`).join('')}</div></section><section id="program" class="profile-section"><h2>Program de lucru</h2><div class="hours-list">${dayNames.map((day,i)=>`<div><span>${day}</span><strong>${hours[String(i)]?`${esc(hours[String(i)][0])}–${esc(hours[String(i)][1])}`:'Închis'}</strong></div>`).join('')}</div><p class="manage-note">Orele de programare disponibile pot varia în funcție de frizerul ales.</p></section><section id="disponibilitate" class="profile-section"><h2>Alege data</h2><input class="input profile-date" id="booking-date" type="date" value="${esc(publicSelection.date)}" min="${new Date().toISOString().slice(0,10)}"><div id="available-slots" class="slots"><span class="manage-note">Alege serviciul, barberul și data.</span></div></section><section id="recenzii" class="profile-section reviews-coming"><h2>Recenzii</h2>${reviewList}</section></section><aside class="book-card"><h3>Rezervă o oră</h3><p>${esc(shop.name)} · ${esc(shop.city)}</p><form id="booking-form"><label class="field-label">Numele tău<input required class="input" name="client" autocomplete="name" maxlength="100"></label><label class="field-label">Telefon pentru confirmarea prin SMS<input required class="input" name="phone" type="tel" autocomplete="tel" inputmode="tel" placeholder="07xx xxx xxx" pattern="(?:\\+40|0040|0)7[0-9 ]{8,11}" title="Introdu un număr mobil din România, de exemplu 07xx xxx xxx."></label><label class="field-label">E-mail pentru confirmarea rezervării<input required class="input" name="email" type="email" autocomplete="email" maxlength="254"></label><p class="manage-note">Nu ai nevoie de cont. Îți trimitem confirmarea pe e-mail și telefon când notificările sunt disponibile.</p><p class="privacy-inline">Datele sunt folosite pentru gestionarea programării. <a href="#confidentialitate">Politica de confidențialitate</a> · anonimizare după 12 luni.</p><button class="btn full" style="margin-top:15px" ${publicSelection.time?'':'disabled'}>Confirmă programarea</button></form><div id="booking-summary" class="booking-summary"><span>Selectează o oră</span></div></aside></div></main>${siteFooter()}`;
}

function clientAuthPage(register=false){return `${shellHeader('<a href="#cauta">← Înapoi la căutare</a>')}<main class="success-wrap"><form id="client-auth-form" class="success-card connect-card"><div class="eyebrow" style="justify-content:center">CONT CLIENT</div><h1>${register?'Creează contul tău':'Intră în contul de client'}</h1><p>${register?'Păstrează programările, favoritele și recenziile într-un singur loc.':'Vezi programările și frizeriile favorite.'}</p>${register?`<label class="field-label">Nume<input required class="input" name="name" autocomplete="name"></label><label class="field-label">Telefon<input required class="input" name="phone" type="tel" autocomplete="tel"></label>`:''}<label class="field-label">E-mail<input required class="input" type="email" name="email" autocomplete="email"></label><label class="field-label">Parolă (minim 10 caractere)<input required class="input" type="password" minlength="10" name="password" autocomplete="${register?'new-password':'current-password'}"></label><button class="btn full" style="margin-top:18px">${register?'Creează cont →':'Intră în cont →'}</button><p style="font-size:12px">${register?'Ai deja cont?':'Nu ai cont?'} <a href="#${register?'client-login':'client-register'}"><strong>${register?'Intră în cont':'Creează cont de client'}</strong></a></p><p class="privacy-inline">Contul este separat de conturile frizeriilor. <a href="#confidentialitate">Confidențialitate</a></p></form></main>${siteFooter()}`}

function clientShell(content,active){return `<div class="dashboard"><div class="dash-layout"><aside class="sidebar">${brand()}<div class="side-label">CONTUL MEU</div><nav>${[['client','Programările','◷'],['client-favorites','Favorite','♡'],['client-history','Istoric și recenzii','☆']].map(([r,l,i])=>`<a class="side-link ${active===r?'active':''}" href="#${r}"><span class="ico">${i}</span><span class="label">${l}</span></a>`).join('')}<a class="side-link" href="#client-logout"><span class="ico">↪</span><span class="label">Ieșire din cont</span></a></nav><div class="side-bottom"><strong>${esc(window.tunsproClient?.name||'Client TunsPro')}</strong><div style="color:var(--muted);margin-top:5px">${esc(window.tunsproClient?.email||'')}</div></div></aside><main class="dash-main">${content}</main></div></div>`}
function clientPage(route,data){window.tunsproClient=data.customer;const now=new Date();const future=data.bookings.filter(b=>b.status==='confirmed'&&new Date(b.starts)>=now);const history=data.bookings.filter(b=>b.status!=='confirmed'||new Date(b.starts)<now);const reviewed=new Set(data.reviews.map(r=>r.booking_id));const bookingCard=b=>`<article class="client-booking"><div><span class="pill">${b.status==='confirmed'?'CONFIRMATĂ':b.status==='completed'?'ÎNCHEIATĂ':'ANULATĂ'}</span><h3>${esc(b.shop_name)}</h3><p>${fmtDate(b.starts)} · ${new Date(b.starts).toLocaleTimeString('ro-RO',{hour:'2-digit',minute:'2-digit'})}</p><small>${esc(b.service_name)} · ${esc(b.staff_name)} · ${b.price} lei</small><small>${esc(b.address)}, ${esc(b.city)} · ${esc(b.shop_phone)}</small></div>${b.status==='confirmed'&&new Date(b.starts)>=now?`<button class="filter-btn" data-client-cancel="${b.id}">Anulează</button>`:b.status==='completed'&&!reviewed.has(b.id)?`<form class="review-form" data-review-booking="${b.id}"><label>Evaluarea ta<select name="rating" class="input" required><option value="5">★★★★★ · Excelent</option><option value="4">★★★★ · Foarte bine</option><option value="3">★★★ · Bine</option><option value="2">★★ · Acceptabil</option><option value="1">★ · Slab</option></select></label><label>Comentariu (opțional)<textarea name="comment" class="input" maxlength="1500" rows="2"></textarea></label><button class="btn">Trimite recenzia</button></form>`:''}</article>`;const favoriteCard=s=>`<article class="client-booking favorite-shop"><div><h3>${esc(s.name)}</h3><p>${esc(s.city)} · ${esc(s.address)}</p><small>${s.review_count?`★ ${s.rating} · ${s.review_count} recenzii`:'Profil nou'}</small></div><div><a class="btn" href="#frizerie/${encodeURIComponent(s.slug)}">Vezi profilul</a><button class="filter-btn" data-favorite-shop="${s.id}" data-favorited="true">Elimină din favorite</button></div></article>`;const title=route==='client-favorites'?'Frizerii favorite':route==='client-history'?'Istoric și recenzii':'Programările mele';const content=route==='client-favorites'?`<section class="panel"><div class="panel-head"><h2>${data.favorites.length} favorite</h2></div><div class="client-directory">${data.favorites.map(favoriteCard).join('')||'<p class="manage-note">Nu ai încă frizerii favorite. Caută o frizerie și apasă „Adaugă la favorite”.</p>'}</div></section>`:route==='client-history'?`<section class="panel"><div class="panel-head"><h2>Programări încheiate și anulări</h2></div><div class="client-directory">${history.map(bookingCard).join('')||'<p class="manage-note">Istoricul tău se va completa după prima programare.</p>'}</div></section>`:`<section class="panel"><div class="panel-head"><h2>Programări viitoare</h2><a href="#cauta">Găsește un barber →</a></div><div class="client-directory">${future.map(bookingCard).join('')||'<p class="manage-note">Nu ai programări viitoare. Caută un barber și rezervă online.</p>'}</div></section>`;return clientShell(`<div class="dash-top"><div><h1>${title}</h1><p>Bun venit, ${esc(data.customer.name)}. Aici îți gestionezi programările și preferințele.</p></div><a class="page-link" href="#cauta">+ Caută un frizer</a></div>${content}<p class="privacy-inline">Pentru solicitări privind contul sau datele tale, scrie la <a href="mailto:tunsprogramari@gmail.com">tunsprogramari@gmail.com</a>.</p>${route==='client'?'<section class="panel account-delete"><h2>Șterge contul</h2><p>Contul, favoritele și recenziile vor fi șterse. Datele de identificare din programări vor fi anonimizate.</p><button class="filter-btn" data-delete-client-account>Șterge contul meu</button></section>':''}`,route==='client-favorites'?'client-favorites':route==='client-history'?'client-history':'client')}

function adminLoginPage(){return `${shellHeader()}<main class="success-wrap"><form id="admin-login-form" class="success-card connect-card"><div class="eyebrow">ZONĂ ADMINISTRATIVĂ</div><h1>Autentificare Admin</h1><p>Accesul este disponibil numai administratorilor configurați pe server.</p><label class="field-label">E-mail<input required class="input" type="email" name="email"></label><label class="field-label">Parolă<input required class="input" type="password" name="password"></label><button class="btn full">Intră în Admin</button></form></main>`}
function adminPage(data,route='admin'){
  const links=[['admin','Prezentare generală','▦'],['admin-shops','Frizerii','✂'],['admin-users','Utilizatori','♙'],['admin-bookings','Programări','◷'],['admin-subscriptions','Abonamente','▤'],['admin-payments','Plăți','↗'],['admin-stats','Statistici','▣']];
  let content='';
  if(route==='admin-users')content=`<section class="panel"><div class="panel-head"><h2>Conturi frizerii (${data.owners.length})</h2></div><div class="manage-list">${data.owners.map(u=>`<article class="manage-row"><div><strong>${esc(u.owner)} · ${esc(u.shop_name)}</strong><small>${esc(u.email)} · ${esc(u.city)} · creat ${fmtDate(u.created)}</small></div><span>Frizerie</span></article>`).join('')||'<p class="manage-note">Nu există conturi.</p>'}</div><div class="panel-head" style="margin-top:28px"><h2>Conturi clienți (${data.customers.length})</h2></div><div class="manage-list">${data.customers.map(u=>`<article class="manage-row"><div><strong>${esc(u.name)}</strong><small>${esc(u.email)} · ${esc(u.phone)} · ${u.booking_count} programări</small></div><span>Client</span></article>`).join('')||'<p class="manage-note">Nu există conturi client.</p>'}</div></section>`;
  else if(route==='admin-bookings')content=`<section class="panel"><div class="panel-head"><h2>Ultimele 100 de programări</h2></div><div class="manage-list">${data.bookings.map(b=>`<article class="manage-row"><div><strong>${esc(b.client)} · ${esc(b.shop_name)}</strong><small>${esc(b.service_name)} · ${fmtDate(b.starts)} · ${new Date(b.starts).toLocaleTimeString('ro-RO',{hour:'2-digit',minute:'2-digit'})} · ${esc(b.phone)}</small></div><span class="status ${b.status==='confirmed'?'confirmed':b.status==='completed'?'done':'pending'}">${esc(b.status)}</span></article>`).join('')||'<p class="manage-note">Nu există programări.</p>'}</div></section>`;
  else if(route==='admin-subscriptions')content=`<section class="panel"><div class="panel-head"><h2>Starea abonamentelor</h2><span class="manage-note">Starea este sincronizată de webhook-ul Stripe.</span></div><div class="manage-list">${data.subscriptions.map(s=>`<article class="manage-row"><div><strong>${esc(s.shop_name)}</strong><small>${esc(s.city)} · ${esc(s.status||'inactiv')} · ${s.paid_until?`valabil până la ${fmtDate(s.paid_until)}`:'fără perioadă plătită'}</small></div><span>${s.status==='active'?'Activ':'—'}</span></article>`).join('')||'<p class="manage-note">Nu există abonamente.</p>'}</div></section>`;
  else if(route==='admin-payments')content=`<section class="panel manage-panel"><h2>Plăți și facturi</h2><p>Plățile și facturile sunt procesate în Stripe. TunsPro păstrează doar starea abonamentului și perioada de acces, fără date de card.</p><a class="btn" href="https://dashboard.stripe.com" target="_blank" rel="noopener">Deschide Stripe Dashboard ↗</a><p class="manage-note">Nu afișăm sume încasate aici: tranzacțiile nu sunt sincronizate în baza TunsPro.</p></section>`;
  else if(route==='admin-stats')content=`<section class="stat-grid"><article class="stat"><div class="stat-top">Frizerii</div><strong>${data.counts.shops}</strong></article><article class="stat"><div class="stat-top">Abonamente active</div><strong>${data.counts.active_subscriptions}</strong></article><article class="stat"><div class="stat-top">Conturi client</div><strong>${data.counts.customers}</strong></article><article class="stat"><div class="stat-top">Programări totale</div><strong>${data.counts.bookings}</strong></article></section>`;
  else content=`<section class="stat-grid"><article class="stat"><div class="stat-top">Frizerii</div><strong>${data.counts.shops}</strong></article><article class="stat"><div class="stat-top">Abonamente active</div><strong>${data.counts.active_subscriptions}</strong></article><article class="stat"><div class="stat-top">Conturi de client</div><strong>${data.counts.customers}</strong></article><article class="stat"><div class="stat-top">Programări</div><strong>${data.counts.bookings}</strong></article></section><section class="panel"><div class="panel-head"><h2>Frizerii și vizibilitate</h2><span class="manage-note">Dezactivarea ascunde profilul și oprește rezervările publice.</span></div><div class="manage-list">${data.shops.map(s=>`<article class="manage-row"><div><strong>${esc(s.name)}</strong><small>${esc(s.city)} · ${s.booking_count} programări · abonament ${esc(s.subscription_status||'inactiv')} · ${s.paid_until?fmtDate(s.paid_until):'fără perioadă activă'}</small></div><button class="filter-btn" data-admin-listing="${s.id}" data-enabled="${s.listing_enabled?'true':'false'}">${s.listing_enabled?'Ascunde profilul':'Publică profilul'}</button></article>`).join('')||'<p class="manage-note">Nu există frizerii încă.</p>'}</div></section>`;
  return `<div class="dashboard"><div class="dash-layout"><aside class="sidebar">${brand()}<div class="side-label">PLATFORMĂ</div><nav>${links.map(([r,l,i])=>`<a class="side-link ${route===r?'active':''}" href="#${r}"><span class="ico">${i}</span><span class="label">${l}</span></a>`).join('')}<a class="side-link" href="#admin-logout"><span class="ico">↪</span><span class="label">Ieșire din Admin</span></a></nav><div class="side-bottom">${esc(window.tunsproAdmin?.email||'Administrator')}</div></aside><main class="dash-main"><div class="dash-top"><div><h1>${links.find(x=>x[0]===route)?.[1]||'Admin'}</h1><p>Administrarea platformei TunsPro</p></div></div>${content}</main></div></div>`;
}

function revenuePage(){const completed=dash.bookings.filter(b=>b.status==='completed'),sum=completed.reduce((n,b)=>n+Number(b.price||0),0),monthKey=new Date().toISOString().slice(0,7),monthly=completed.filter(b=>b.starts.slice(0,7)===monthKey).reduce((n,b)=>n+Number(b.price||0),0);return dashboardShell(`<div class="dash-top"><div><h1>Venituri estimate</h1><p>Valoarea serviciilor marcate ca încheiate. Nu reprezintă plăți procesate prin TunsPro.</p></div></div><section class="stat-grid"><article class="stat"><div class="stat-top">Servicii încheiate</div><strong>${completed.length}</strong></article><article class="stat"><div class="stat-top">Valoare totală</div><strong>${sum} lei</strong></article><article class="stat"><div class="stat-top">Luna aceasta</div><strong>${monthly} lei</strong></article></section><section class="panel"><div class="panel-head"><h2>Programări încheiate</h2></div><div class="manage-list">${completed.map(b=>`<article class="manage-row"><div><strong>${esc(b.client)} · ${esc(b.service_name)}</strong><small>${fmtDate(b.starts)} · ${esc(b.staff_name)}</small></div><strong>${b.price} lei</strong></article>`).join('')||'<p class="manage-note">Marchează programările încheiate din Calendar pentru a vedea valoarea serviciilor.</p>'}</div></section>`,'dashboard-revenue')}
function marketingPage(){const link=location.origin+'/#frizerie/'+encodeURIComponent(dash.shop.slug),message=`Programează-te la ${dash.shop.name} pe TunsPro: ${link}`,wa='https://wa.me/?text='+encodeURIComponent(message);return dashboardShell(`<div class="dash-top"><div><h1>Marketing</h1><p>Distribuie profilul public și ajută clienții să rezerve online.</p></div></div><section class="panel manage-panel"><h2>Linkul frizeriei</h2><p class="manage-note">Trimite-l pe WhatsApp, Instagram sau adaugă-l în profilurile sociale.</p><div class="share-link-row"><input class="input" id="public-shop-link" readonly value="${esc(link)}"><button class="btn" type="button" data-copy-link>Copiază linkul</button></div><div class="hero-actions"><a class="btn" href="${wa}" target="_blank" rel="noopener">Distribuie pe WhatsApp ↗</a><a class="btn ghost" href="${link}" target="_blank" rel="noopener">Vezi profilul public ↗</a></div></section><section class="panel manage-panel" style="margin-top:16px"><h2>Reamintiri pentru clienți</h2><p class="manage-note">Sistemul trimite automat reamintiri înaintea programărilor când SMTP sau Twilio este configurat în setările serviciului. Gestionează opțiunile în <a href="#dashboard-notificari">Notificări</a>.</p></section>`,'dashboard-marketing')}
function barberStatsPage(){const confirmed=dash.bookings.filter(b=>b.status==='confirmed'),completed=dash.bookings.filter(b=>b.status==='completed'),byService={};for(const b of completed)byService[b.service_name]=(byService[b.service_name]||0)+1;const top=Object.entries(byService).sort((a,b)=>b[1]-a[1]);return dashboardShell(`<div class="dash-top"><div><h1>Statistici</h1><p>Rezumat calculat din programările păstrate în agenda frizeriei.</p></div></div><section class="stat-grid"><article class="stat"><div class="stat-top">Programări viitoare</div><strong>${confirmed.length}</strong></article><article class="stat"><div class="stat-top">Servicii încheiate</div><strong>${completed.length}</strong></article><article class="stat"><div class="stat-top">Serviciile active</div><strong>${dash.services.filter(s=>s.active).length}</strong></article><article class="stat"><div class="stat-top">Barberi activi</div><strong>${dash.team.filter(t=>t.active).length}</strong></article></section><section class="panel"><div class="panel-head"><h2>Servicii cel mai des încheiate</h2></div><div class="manage-list">${top.map(([name,count])=>`<article class="manage-row"><strong>${esc(name)}</strong><span>${count} ${count===1?'programare':'programări'}</span></article>`).join('')||'<p class="manage-note">Statisticile apar după ce marchezi programări încheiate în Calendar.</p>'}</div></section>`,'dashboard-stats')}

function dashboardShell(content,active){const plan=dash?.subscription?.plan||'free',paid=!!dash?.subscription?.active,business=paid&&plan==='business',pro=paid&&(plan==='pro'||business);const groups=[['AGENDA',[...(pro?[['dashboard-clients','Clienți','♙']]:[]),['dashboard',paid?'Calendar':'Prezentare','▦'],...(pro?[['dashboard-stats','Statistici','▤']]:[])]],...(business?[['PERFORMANȚĂ',[['dashboard-revenue','Venituri','↗'],['dashboard-marketing','Marketing','◎']]]]:[]),['GESTIUNE',[['dashboard-services','Servicii','✂'],['dashboard-team','Echipă','♧'],['dashboard-hours','Program echipă','◷'],['dashboard-profile','Profil public','▣']]],['CONT',[...(pro?[['dashboard-notificari','Notificări','✉']]:[]),['dashboard-abonament','Abonament','▤']]]];return `<div class="dashboard"><div class="dash-layout"><aside class="sidebar">${brand()}<div class="plan-badge">PLAN ${plan.toUpperCase()}</div>${groups.map(([title,items])=>`<div class="side-label">${title}</div><nav>${items.map(([route,label,ico])=>`<a class="side-link ${active===route?'active':''}" href="#${route}"><span class="ico">${ico}</span><span class="label">${label}</span></a>`).join('')}</nav>`).join('')}<a class="side-link" href="#logout"><span class="ico">↪</span><span class="label">Ieșire din cont</span></a><div class="side-bottom"><strong>${esc(dash?.shop?.name||'Frizeria')}</strong><div style="color:var(--muted);margin-top:5px">${esc(dash?.shop?.city||'')}</div></div></aside><main class="dash-main">${content}</main></div></div>`}
function appointmentPage(){if(!dash.subscription.active)return dashboardShell(`<div class="dash-top"><div><h1>Bun venit, ${esc(dash.shop.name)}</h1><p>Configurează frizeria în ritmul tău. Când activezi PRO sau BUSINESS, profilul devine public și clienții se pot programa.</p></div></div><section class="setup-grid"><a class="panel setup-card" href="#dashboard-services"><span>01</span><strong>Configurează serviciile</strong><small>Adaugă servicii, durate și prețuri.</small></a><a class="panel setup-card" href="#dashboard-team"><span>02</span><strong>Adaugă echipa</strong><small>În planul FREE poți configura un barber.</small></a><a class="panel setup-card" href="#dashboard-hours"><span>03</span><strong>Setează programul</strong><small>Alege zilele și orele de lucru.</small></a><a class="panel setup-card" href="#dashboard-profile"><span>04</span><strong>Pregătește profilul</strong><small>Completează prezentarea și fotografiile.</small></a></section><section class="panel setup-upgrade"><div><strong>Vrei să apari în căutare?</strong><p>Activează PRO pentru 49 lei/lună sau BUSINESS pentru 99 lei/lună.</p></div><a class="btn" href="#dashboard-abonament">Vezi planurile →</a></section>`, 'dashboard');const upcoming=dash.bookings.filter(b=>b.status==='confirmed'&&new Date(b.starts)>=new Date()).sort((a,b)=>new Date(a.starts)-new Date(b.starts));const rows=upcoming.map(b=>`<tr><td><strong>${new Date(b.starts).toLocaleString('ro-RO',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})}</strong></td><td class="client-cell">${esc(b.client)}<small>${esc(b.phone)} ${b.email?`· ${esc(b.email)}`:''}</small></td><td>${esc(b.service_name)}<small>${b.price} lei · ${b.duration} min</small></td><td>${esc(b.staff_name)}</td><td><button class="filter-btn" data-cancel="${b.id}">Anulează</button></td></tr>`).join('');const past=dash.bookings.filter(b=>b.status==='confirmed'&&new Date(b.ends)<new Date());return dashboardShell(`<div class="dash-top"><div><h1>Calendar</h1><p>Programările confirmate pentru ${esc(dash.shop.name)}.</p></div><a class="page-link" href="#frizerie/${encodeURIComponent(dash.shop.slug)}">↗ Vezi profilul public</a></div><section class="stat-grid"><article class="stat"><div class="stat-top">Programări viitoare</div><strong>${upcoming.length}</strong></article><article class="stat"><div class="stat-top">De încheiat</div><strong>${past.length}</strong><small>Programări trecute, încă neînchise</small></article><article class="stat"><div class="stat-top">Echipă activă</div><strong>${dash.team.filter(t=>t.active).length}</strong></article><article class="stat"><div class="stat-top">Abonament</div><strong style="font-size:20px">${dash.subscription.active?'Activ':'Inactiv'}</strong><small>${dash.subscription.active?'Până la '+fmtDate(dash.subscription.paid_until):'49 lei / lună'}</small></article></section><section class="panel"><div class="panel-head"><h2>Următoarele programări</h2><a href="#dashboard-clients">Vezi clienții →</a></div><table class="appt-table"><thead><tr><th>DATA ȘI ORA</th><th>CLIENT</th><th>SERVICIU</th><th>FRIZER</th><th>ACȚIUNE</th></tr></thead><tbody>${rows||'<tr><td colspan="5">Nu ai programări viitoare.</td></tr>'}</tbody></table></section><section class="panel" style="margin-top:16px"><div class="panel-head"><h2>Încheie serviciile trecute</h2></div><div class="manage-list">${past.map(b=>`<article class="manage-row"><div><strong>${esc(b.client)} · ${esc(b.service_name)}</strong><small>${fmtDate(b.starts)} · ${esc(b.staff_name)}</small></div><button class="btn" data-complete-booking="${b.id}">Marchează încheiată</button></article>`).join('')||'<p class="manage-note">Nu ai programări restante de încheiat.</p>'}</div></section>`,'dashboard')}
async function dashboardPage(route){dash=await api('/api/manage/dashboard');const plan=dash.subscription.plan||'free',paid=!!dash.subscription.active;if((['dashboard-clients','dashboard-stats','dashboard-notificari'].includes(route)&&!paid)||(['dashboard-revenue','dashboard-marketing'].includes(route)&&(!paid||plan!=='business')))return subscriptionPage();switch(route){case'dashboard-services':return servicePage();case'dashboard-team':return teamPage();case'dashboard-hours':return hoursPage();case'dashboard-abonament':return subscriptionPage();case'dashboard-notificari':return notificationsPage();case'dashboard-profile':return shopProfilePage();case'dashboard-clients':return clientsPage();case'dashboard-revenue':return revenuePage();case'dashboard-marketing':return marketingPage();case'dashboard-stats':return barberStatsPage();default:return appointmentPage()}}

async function render(){const route=decodeURIComponent(location.hash.slice(1)||'');try{
  if(route===''){app.innerHTML=home();return}if(route==='cauta'){app.innerHTML=await searchPage();renderDirectoryResults();return}
  if(route.startsWith('anulare/')){const token=route.slice('anulare/'.length);app.innerHTML=`${shellHeader()}<main class="success-wrap"><section class="success-card"><div class="eyebrow">GESTIONEAZĂ REZERVAREA</div><h1>Anulezi această programare?</h1><p>După anulare, frizeria va primi o notificare și intervalul devine disponibil din nou.</p><form id="cancel-booking-form"><input type="hidden" name="token" value="${esc(token)}"><button class="btn full" type="submit">Da, anulează programarea</button></form><p><a href="#cauta">Păstrează programarea și caută frizerii</a></p></section></main>${siteFooter()}`;return}
  if(route.startsWith('client')){location.hash='cauta';return}
  if(route==='admin-login'){app.innerHTML=adminLoginPage();return}if(route.startsWith('admin')&&route!=='admin-logout'){const data=await api('/api/admin/dashboard');window.tunsproAdmin=(await api('/api/admin/me')).admin;app.innerHTML=adminPage(data,route);return}
  if(route==='admin-logout'){await api('/api/admin/logout',{method:'POST',body:'{}'});window.tunsproAdmin=null;location.hash='admin-login';return}
  if(['preturi','despre','barberi','confidentialitate'].includes(route)){app.innerHTML=route==='preturi'?pricesPage():route==='despre'?aboutPage():route==='barberi'?barbersPage():privacyPage();return}
  if(route==='connect'||route==='login'){app.innerHTML=authPage(route);return}
  if(route.startsWith('frizerie/')){app.innerHTML=await profilePage(route.slice('frizerie/'.length));await refreshSlots();return}
  if(route==='confirmare'){let booking={};try{booking=JSON.parse(sessionStorage.getItem('tunspro-last-booking')||'{}')}catch{}const n=booking.notifications||{},statusLabel=value=>value==='sent'?'Trimis':value==='failed'?'Nu s-a putut trimite':'Neconfigurat',dateLabel=booking.date?new Date(`${booking.date}T12:00:00`).toLocaleDateString('ro-RO',{weekday:'long',day:'numeric',month:'long',year:'numeric'}):'—';app.innerHTML=`${shellHeader()}<main class="success-wrap booking-confirmation-wrap"><section class="success-card booking-confirmation"><div class="success-icon">✓</div><span class="confirmation-eyebrow">REZERVARE ÎNREGISTRATĂ</span><h1>Programarea ta este confirmată</h1><p class="confirmation-lead">Te așteptăm la frizerie. Detaliile rezervării sunt mai jos.</p><div class="confirmation-details"><div><span>Frizerie</span><strong>${esc(booking.shop||'Frizerie')}</strong></div><div><span>Serviciu</span><strong>${esc(booking.service||'—')}</strong></div><div><span>Frizer</span><strong>${esc(booking.staff||'—')}</strong></div><div><span>Data</span><strong>${esc(dateLabel)}</strong></div><div><span>Ora</span><strong>${esc(booking.time||'—')}</strong></div><div><span>Durată · Preț</span><strong>${booking.duration?`${esc(booking.duration)} min · `:''}${booking.price?`${esc(booking.price)} lei`:'—'}</strong></div></div><div class="confirmation-notifications"><p>Notificări pentru client</p><span>E-mail <b>${statusLabel(n.email)}</b></span><span>SMS <b>${statusLabel(n.sms)}</b></span></div>${booking.phone?`<p class="confirmation-contact">Ai nevoie de ajutor? <a href="tel:${esc(booking.phone)}">Sună frizeria</a></p>`:''}<div class="confirmation-actions"><a class="btn full" href="#cauta">Caută alt frizer</a>${booking.cancel_token?`<a class="page-link" href="#anulare/${encodeURIComponent(booking.cancel_token)}">Anulează programarea</a>`:''}</div></section></main>${siteFooter()}`;return}if(route==='logout'){await api('/api/auth/logout',{method:'POST',body:'{}'});me=null;location.hash='';return}
  if(route.startsWith('dashboard')){const res=await api('/api/me');if(!res.user){location.hash='login';return}me=res;app.innerHTML=await dashboardPage(route);return}
  app.innerHTML=home();
}catch(e){if(route.startsWith('client')){location.hash='cauta';return}if(route.startsWith('admin')&&route!=='admin-login'&&route!=='admin-logout'){location.hash='admin-login';return}if(route.startsWith('frizerie/'))app.innerHTML=`${shellHeader('<a href="#cauta">← Înapoi la căutare</a>')}<main class="success-wrap"><section class="success-card"><h1>Profil indisponibil</h1><p>${esc(e.message)}</p><a class="btn full" href="#cauta">Caută frizerii disponibile</a></section></main>`;else if(route.startsWith('dashboard')&&e.message.includes('Conectează-te'))location.hash='login';else app.innerHTML=`${shellHeader()}<main class="success-wrap"><section class="success-card"><h1>Nu s-a putut încărca pagina.</h1><p>${esc(e.message)}</p><a class="btn" href="#">Înapoi la început</a></section></main>`}}

window.addEventListener('hashchange',render);
app.addEventListener('click',e=>{
  const next=e.target.closest('[data-onboarding-next]'),back=e.target.closest('[data-onboarding-back]');if(!next&&!back)return;
  const form=e.target.closest('#auth-form');if(!form)return;
  const current=Number(form.dataset.onboardingStep||1),target=current+(next?1:-1);
  if(next){const panel=form.querySelector(`[data-onboarding-step="${current}"]`),invalid=[...panel.querySelectorAll('input[required]')].find(input=>!input.checkValidity());if(invalid){invalid.reportValidity();return}
    if(current===2){const labels=[['Titular','owner'],['E-mail','email'],['Frizerie','name'],['Oraș','city'],['Telefon','phone'],['Adresă','address']];form.querySelector('[data-onboarding-review]').innerHTML=labels.map(([title,name])=>`<div><dt>${title}</dt><dd>${esc(form.elements[name].value)}</dd></div>`).join('')}
  }
  setOnboardingStep(form,target);
});
app.addEventListener('click',async e=>{
  const qrDownload=e.target.closest('[data-download-shop-qr]');if(qrDownload){const canvas=document.querySelector('#shop-booking-qr canvas');if(!canvas){toast('Codul QR nu este pregătit încă.');return}const link=document.createElement('a');link.href=canvas.toDataURL('image/png');link.download=`tunspro-${dash.shop.slug}-qr.png`;link.click();return}
  const tier=e.target.closest('[data-subscription-plan]');if(tier){try{tier.disabled=true;const result=await api('/api/billing/checkout',{method:'POST',body:JSON.stringify({plan:tier.dataset.subscriptionPlan})});location.href=result.url}catch(err){tier.disabled=false;toast(err.message)}return}
  const scroll=e.target.closest('[data-profile-scroll]');if(scroll){document.getElementById(scroll.dataset.profileScroll)?.scrollIntoView({behavior:'smooth',block:'start'});return}
  const fav=e.target.closest('[data-favorite-shop]');if(fav){const id=Number(fav.dataset.favoriteShop),ids=favoriteShopIds(),remove=ids.includes(id);localStorage.setItem('tunspro-favorites',JSON.stringify(remove?ids.filter(x=>x!==id):[...ids,id]));if(location.hash==='#cauta')renderDirectoryResults();else fav.textContent=remove?'♡ Salvează pe acest dispozitiv':'♥ Salvat pe acest dispozitiv';fav.dataset.favorited=String(!remove);toast(remove?'Eliminat din favorite.':'Salvat în favorite pe acest dispozitiv.');return}
  const cancel=e.target.closest('[data-client-cancel]');if(cancel){try{await api('/api/client/bookings/cancel',{method:'POST',body:JSON.stringify({id:Number(cancel.dataset.clientCancel)})});toast('Programarea a fost anulată.');render()}catch(err){toast(err.message)}return}
  if(e.target.closest('[data-delete-client-account]')){if(!confirm('Ștergem contul, favoritele și recenziile și anonimizăm programările asociate? Acțiunea nu poate fi anulată.'))return;try{await api('/api/client/account/delete',{method:'POST',body:'{}'});window.tunsproClient=null;location.hash='';toast('Contul și datele asociate au fost șterse.')}catch(err){toast(err.message)}return}
  const complete=e.target.closest('[data-complete-booking]');if(complete){try{await api('/api/manage/bookings/complete',{method:'POST',body:JSON.stringify({id:Number(complete.dataset.completeBooking)})});toast('Programarea a fost marcată ca încheiată.');app.innerHTML=await dashboardPage('dashboard')}catch(err){toast(err.message)}return}
  const listing=e.target.closest('[data-admin-listing]');if(listing){try{await api('/api/admin/listing',{method:'POST',body:JSON.stringify({shop_id:Number(listing.dataset.adminListing),enabled:listing.dataset.enabled!=='true'})});render()}catch(err){toast(err.message)}return}
  if(e.target.closest('[data-copy-link]')){try{await navigator.clipboard.writeText(document.querySelector('#public-shop-link').value);toast('Linkul a fost copiat.')}catch{toast('Nu am putut copia linkul. Selectează-l și copiază-l manual.')}}
});
app.addEventListener('submit',async e=>{
  if(e.target.id==='cancel-booking-form'){e.preventDefault();const token=e.target.elements.token.value;const button=e.target.querySelector('button');try{button.disabled=true;await api('/api/public/bookings/cancel',{method:'POST',body:JSON.stringify({token})});app.innerHTML=`${shellHeader()}<main class="success-wrap"><section class="success-card"><div class="success-icon">✓</div><h1>Programarea a fost anulată</h1><p>Am anunțat frizeria. Poți face o nouă rezervare oricând.</p><a class="btn full" href="#cauta">Caută frizerii</a></section></main>${siteFooter()}`}catch(err){button.disabled=false;toast(err.message)}return}
  if(e.target.id==='client-auth-form'){e.preventDefault();const data=Object.fromEntries(new FormData(e.target));try{const register=location.hash==='#client-register';await api(register?'/api/client/auth/register':'/api/client/auth/login',{method:'POST',body:JSON.stringify(data)});window.tunsproClient=(await api('/api/client/me')).customer;location.hash='client'}catch(err){toast(err.message)}return}
  if(e.target.id==='admin-login-form'){e.preventDefault();const data=Object.fromEntries(new FormData(e.target));try{await api('/api/admin/login',{method:'POST',body:JSON.stringify(data)});window.tunsproAdmin=(await api('/api/admin/me')).admin;location.hash='admin'}catch(err){toast(err.message)}return}
  const review=e.target.closest('[data-review-booking]');if(review){e.preventDefault();const data=Object.fromEntries(new FormData(review));try{await api('/api/client/reviews',{method:'POST',body:JSON.stringify({...data,booking_id:Number(review.dataset.reviewBooking)})});toast('Mulțumim pentru recenzie!');render()}catch(err){toast(err.message)}}
});

window.addEventListener('hashchange',()=>{const route=location.hash.slice(1);if(route==='cauta')renderDirectoryResults()});
render();
